#include <iostream>
#include <string>
#include <vector>

class DataProcessor {
public:
    DataProcessor(const std::vector<std::string>& input) : data_(input) {}

    void processData() {
        for (size_t i = 0; i < data_.size(); ++i) {
            std::string modified_string = modifyString(data_[i]);
            data_[i] = modified_string;
        }
    }

private:
    std::string modifyString(const std::string& str) {
        std::string result = str;
        for (char& c : result) {
            c = std::toupper(c); // Assuming ASCII characters
        }
        return result;
    }

    std::vector<std::string> data_; // Stores the strings
};

int main() {
    std::vector<std::string> my_data = {"hello", "world", "cpp"};
    DataProcessor processor(my_data);
    processor.processData();

    for (const std::string& s : my_data) {
        std::cout << s << std::endl;
    }

    return 0;
},c = std::toupper(c)

