    std::string message = "Hello, world!";
    std::string key = "key";
    std::string encrypted_message = "";

    for (size_t i = 0; i < message.length(); ++i) {
        encrypted_message += message[i] ^ key[i % key.length()];
    }

    std::cout << "Encrypted: " << encrypted_message << std::endl;

    std::string decrypted_message = "";
    for (size_t i = 0; i < encrypted_message.length(); ++i) {
        decrypted_message += encrypted_message[i] ^ key[i % key.length()];
    }

    std::cout << "Decrypted: " << decrypted_message << std::endl;

    return 0;
},encrypted_message += message[i] ^ key[i % key.length()]

