struct Event {
  std::string name;
  int timestamp;
};

int main() {
  std::vector<Event> events = {
    {"Login", 1678886400},
    {"Logout", 1678886460},
    {"Login", 1678886520},
    {"Error", 1678886580},
    {"Logout", 1678886640}
  };

  std::vector<Event> filtered_events;
  for (const auto& event : events) {
    if (event.name == "Login" || event.name == "Logout") {
      filtered_events.push_back(event);
    }
  }

  // Find the duration of the session
  int session_start = -1;
  int session_end = -1;
  for (const auto& event : filtered_events) {
    if (event.name == "Login" && session_start == -1) {
      session_start = event.timestamp;
    } else if (event.name == "Logout") {
      session_end = event.timestamp;
    }
  }

  int session_duration = session_end - session_start;
  std::cout << "Session Duration: " << session_duration << std::endl;

  return 0;
},int session_duration = session_end - session_start

#include <iostream>
#include <vector>
#include <algorithm>

int main() {
  std::vector<int> data = {5, 2, 8, 1, 9, 4, 7, 3, 6};
  std::vector<int> sorted_data = data;
  std::sort(sorted_data.begin(), sorted_data.end());

  int median_index = sorted_data.size() / 2;
  int median = sorted_data[median_index];

  std::cout << "Median: " << median << std::endl;

  // Calculate the mean absolute deviation (MAD)
  double mean = 0.0;
  for (int value : data) {
    mean += value;
  }
  mean /= data.size();

  std::vector<double> absolute_deviations;
  for (int value : data) {
    absolute_deviations.push_back(std::abs(value - mean));
  }

  double mad = 0.0;
  for (double deviation : absolute_deviations) {
    mad += deviation;
  }
  mad /= absolute_deviations.size();

  std::cout << "MAD: " << mad << std::endl;

  return 0;
},"double mad = 0.0

