#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

int main() {
  std::string input_string = "hello world";
  std::vector<char> char_vector(input_string.begin(), input_string.end());

  // Reverse the vector in place
  std::reverse(char_vector.begin(), char_vector.end());

  // Convert the reversed vector back to a string
  std::string reversed_string(char_vector.begin(), char_vector.end());

  // Check if the reversed string is a palindrome
  bool is_palindrome = (reversed_string == input_string);

