#include <iostream>
#include <vector>
#include <algorithm>

int main() {
  std::vector<int> data = {5, 2, 8, 1, 9, 4};
  std::vector<int> sorted_data = data;
  std::sort(sorted_data.begin(), sorted_data.end());

  // Find the median
  size_t size = sorted_data.size();
  double median;
  if (size % 2 == 0) {
    median = (sorted_data[size / 2 - 1] + sorted_data[size / 2]) / 2.0;
  } else {
    median = sorted_data[size / 2];
  }

  // Calculate the mean absolute deviation (MAD)
  double sum_abs_diff = 0.0;
  for (int value : data) {
    sum_abs_diff += std::abs(value - median);
  }
  double mad = sum_abs_diff / size;

  std::cout << "Median: " << median << std::endl;
  std::cout << "MAD: " << mad << std::endl;

  return 0;
},double mad = sum_abs_diff / size

