  std::vector<int> filtered_numbers;
  std::copy_if(numbers.begin(), numbers.end(), std::back_inserter(filtered_numbers), 
                [threshold](int n) { return n > threshold; });

  // Print the filtered numbers
  std::cout << "Numbers greater than " << threshold << ":";
  for (int number : filtered_numbers) {
    std::cout << " " << number;
  }
  std::cout << std::endl;

  // Calculate the sum of the filtered numbers using a lambda
  auto sum_func = [&filtered_numbers]() {
    int sum = 0;
    for (int number : filtered_numbers) {
      sum += number;
    }
    return sum;
  };

  // Print the sum
  std::cout << "Sum of filtered numbers: " << sum_func() << std::endl;

  return 0;
},[threshold](int n) { return n > threshold

