  int target = 5;

  // Find the first element greater than the target
  auto it = std::find_if(data.begin(), data.end(), [target](int x) { return x > target; });

  if (it != data.end()) {
    // Calculate the distance to the first element greater than the target
    size_t index = std::distance(data.begin(), it);
    std::cout << "First element greater than " << target << " is at index: " << index << std::endl;
  }
  else {
    std::cout << "No element greater than " << target << " found." << std::endl;
  }

  //Shift all elements after the found element to the left
  if (it != data.end()) {
      std::rotate(data.begin(), it, data.end());
  }

  // Print the modified vector
  for (int value : data) {
    std::cout << value << " ";
  }
  std::cout << std::endl;

  return 0;
},"std::rotate(data.begin(), it, data.end())

