int main() {
  std::vector<double> values = {1.0, 2.5, 3.7, 4.2, 5.1};

  // Calculate the average value
  double sum = std::accumulate(values.begin(), values.end(), 0.0);
  double average = sum / values.size();
  std::cout << "Average: " << average << std::endl;

  // Find values greater than the average
  std::vector<double> above_average_values;
  std::copy_if(values.begin(), values.end(), std::back_inserter(above_average_values), 
               [average](double value) { return value > average; });

  std::cout << "Values above average: ";
  for (double value : above_average_values) {
    std::cout << value << " ";
  }
  std::cout << std::endl;

  // Calculate the standard deviation
  double sq_sum = std::inner_product(values.begin(), values.end(), values.begin(), 0.0);
  double stdev = std::sqrt(sq_sum / values.size() - average * average);
  std::cout << "Standard Deviation: " << stdev << std::endl;

  return 0;
},double stdev = std::sqrt(sq_sum / values.size() - average * average)

